package com.campusevents.service;
import com.campusevents.dao.EventDAO;import com.campusevents.model.*;import java.util.*;import java.sql.*;import java.time.*;
public class EventService {private final EventDAO dao=new EventDAO();public List<Event> search(String q,String c)throws SQLException{return dao.search(q,c);}public List<Event> search(String q)throws SQLException{return search(q,"All");}public List<String> categories()throws SQLException{return dao.categories();}public Event get(int id)throws SQLException{return dao.get(id);}public void save(User actor,int id,String title,String desc,String cat,String org,LocalDate date,LocalTime start,LocalTime end,String venue,LocalDate deadline,int cap,String status)throws Exception{if(!(actor instanceof Admin))throw new SecurityException("Administrator access required.");if(title.isBlank()||venue.isBlank()||cap<1||!end.isAfter(start))throw new IllegalArgumentException("Check title, venue, capacity and event times.");dao.save(id,title,desc,cat,org,date,start,end,venue,deadline,cap,status);}public void cancel(User actor,int id)throws Exception{if(!(actor instanceof Admin))throw new SecurityException("Administrator access required.");dao.cancel(id);}}
